(async () => {
  const getChildren = (node) => {
    return (node.children || []).map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      childrenCount: c.children ? c.children.length : 0
    }));
  };

  const result = {};
  for (const p of figma.root.children) {
    result[p.name] = getChildren(p);
  }
  return result;
})()

(async () => {
  const compFrame = figma.getNodeById("1:19");
  const mediaFrame = figma.getNodeById("1:371");

  const getTree = (node, depth = 0) => {
    if (depth > 3) return { id: node.id, name: node.name, type: node.type };
    const res = { id: node.id, name: node.name, type: node.type };
    if (node.children) {
      res.children = node.children.map(c => getTree(c, depth + 1));
    }
    return res;
  };

  return {
    components: getTree(compFrame),
    media: getTree(mediaFrame)
  };
})()

