(async () => {
  const workspacePage = figma.root.findChild(p => p.name === "03 · Workspace");
  const frames = workspacePage.children.filter(n => n.type === "FRAME");

  // Find duplicates
  const seen = new Set();
  const toRemove = [];

  for (const f of frames) {
    if (seen.has(f.name)) {
      toRemove.push(f);
    } else {
      seen.add(f.name);
    }
  }

  toRemove.forEach(f => f.remove());
  return `Removed ${toRemove.length} duplicate frames.`;
})()

